import 'package:flutter/semantics.dart';
import 'package:flutter/services.dart';
import '../../data/services/tts_service.dart';

/// Los cuatro patrones de vibración de docs/04-design-system.md. Cada uno
/// tiene un significado fijo: nunca se usan al revés.
enum TipoVibracion { cambioFoco, accionEjecutada, confirmacionImportante, error }

extension EjecutarVibracion on TipoVibracion {
  void ejecutar() {
    switch (this) {
      case TipoVibracion.cambioFoco:
        HapticFeedback.selectionClick();
        break;
      case TipoVibracion.accionEjecutada:
        HapticFeedback.lightImpact();
        break;
      case TipoVibracion.confirmacionImportante:
        HapticFeedback.mediumImpact();
        break;
      case TipoVibracion.error:
        HapticFeedback.heavyImpact();
        break;
    }
  }
}

/// Une las tres formas de confirmar una acción: voz, vibración y el lector
/// de pantalla del sistema (RNF-06). Es la pieza más usada de todo el
/// proyecto — toda la app pasa por aquí. Si algo cambia en la pantalla y no
/// se anuncia con esto, para el usuario ciego ese cambio no existe
/// (docs/03-arquitectura.md).
class Anunciador {
  final TtsService _tts;

  Anunciador(this._tts);

  /// Anuncia [mensaje] por voz, vibra y lo entrega también al lector de
  /// pantalla del sistema (TalkBack/VoiceOver), para quien lo tenga activo.
  /// [interrumpir] corta lo que se esté diciendo — útil para avisos urgentes
  /// como los de la guía de captura de Ojo IA.
  Future<void> anunciar(
    String mensaje, {
    bool interrumpir = false,
    TipoVibracion vibracion = TipoVibracion.cambioFoco,
  }) async {
    vibracion.ejecutar();
    // `announce` está marcado obsoleto a favor de `sendAnnouncement`, que
    // pide una `FlutterView` — eso obligaría a pasar un `BuildContext` por
    // todos los controladores (home, lector, ojo_ia...) que hoy no lo
    // necesitan. Sigue funcionando igual en TalkBack; se migra si Flutter
    // llega a quitarlo de verdad.
    // ignore: deprecated_member_use
    SemanticsService.announce(mensaje, TextDirection.ltr);
    await _tts.hablar(mensaje, interrumpir: interrumpir);
  }

  Future<void> detener() => _tts.detener();
}

/// Los comandos de voz que VÍA reconoce (RF-15, RF-16). Cada uno tiene
/// varias formas de decirlo porque nadie memoriza una sintaxis exacta, y el
/// reconocimiento de voz rara vez transcribe una frase perfecta.
enum ComandoVia {
  leerDocumento,
  abrirCamara,
  ajustes,
  inicio,
  repetir,
  parar,
  masRapido,
  masLento,
  ayudaHumana,
  pausar,
  reanudar,
  siguiente,
  anterior,
  indice,
  opcionUno,
  opcionDos,
  opcionTres,
}

class ComandosVoz {
  ComandosVoz._();

  static const Map<ComandoVia, List<String>> _frases = {
    ComandoVia.leerDocumento: [
      'leer documento',
      'leer un documento',
      'abrir documento',
      'leer archivo',
    ],
    ComandoVia.abrirCamara: [
      'abrir camara',
      'abrir la camara',
      'ojo ia',
      'usar camara',
    ],
    ComandoVia.ajustes: ['ajustes', 'configuracion', 'abrir ajustes'],
    ComandoVia.inicio: ['ir a inicio', 'ir al inicio', 'volver a inicio', 'pantalla de inicio'],
    ComandoVia.repetir: ['repetir', 'repite', 'otra vez', 'dilo de nuevo'],
    ComandoVia.parar: ['parar', 'detener', 'silencio', 'callate'],
    ComandoVia.masRapido: ['mas rapido', 'mas veloz', 'acelerar', 'habla mas rapido'],
    ComandoVia.masLento: ['mas lento', 'mas despacio', 'habla mas lento'],
    ComandoVia.ayudaHumana: [
      'ayuda humana',
      'quiero ayuda humana',
      'conectar con un voluntario',
      'necesito ayuda humana',
    ],
    ComandoVia.pausar: ['pausar', 'pausa'],
    ComandoVia.reanudar: ['reanudar', 'continuar', 'seguir leyendo'],
    ComandoVia.siguiente: ['siguiente', 'avanzar', 'pasar'],
    ComandoVia.anterior: ['anterior', 'atras', 'retroceder'],
    ComandoVia.indice: ['indice', 'ver indice', 'lista de encabezados'],
    ComandoVia.opcionUno: ['uno', 'opcion uno', 'primera opcion', 'la primera'],
    ComandoVia.opcionDos: ['dos', 'opcion dos', 'segunda opcion', 'la segunda'],
    ComandoVia.opcionTres: ['tres', 'opcion tres', 'tercera opcion', 'la tercera'],
  };

  /// Devuelve la lista de frases de ejemplo de un comando, para mostrarlas
  /// como ayuda en pantalla.
  static List<String> frasesDe(ComandoVia comando) => _frases[comando] ?? [];

  /// Busca en [textoEscuchado] alguna frase conocida. No exige coincidencia
  /// exacta: basta con que el texto la contenga.
  static ComandoVia? reconocer(String textoEscuchado) {
    final normalizado = _normalizar(textoEscuchado);
    if (normalizado.isEmpty) return null;
    for (final entrada in _frases.entries) {
      for (final frase in entrada.value) {
        if (normalizado.contains(frase)) return entrada.key;
      }
    }
    return null;
  }

  static String _normalizar(String texto) {
    var t = texto.toLowerCase().trim();
    const acentos = {
      'á': 'a', 'é': 'e', 'í': 'i', 'ó': 'o', 'ú': 'u', 'ñ': 'n',
    };
    for (final entrada in acentos.entries) {
      t = t.replaceAll(entrada.key, entrada.value);
    }
    return t;
  }
}

import 'package:flutter/material.dart';
import '../../data/models/documento_leido.dart';
import '../../data/models/perfil_accesibilidad.dart';
import '../../data/services/preferencias_service.dart';
import '../../data/services/tts_service.dart';
import '../accessibility/anunciador.dart';
import '../theme/colores.dart';

/// El estado global de VÍA: los ajustes de accesibilidad del usuario, el
/// motor de voz y el anunciador. Se expone con `provider` (el paquete de
/// estado elegido en docs/CLAUDE.md) para que cualquier pantalla lo lea y
/// cualquier cambio — cambiar el esquema de color, subir el tamaño de
/// texto — repinte la app entera al instante, sin reiniciar nada (Fase 6).
class PerfilProvider extends ChangeNotifier {
  final PreferenciasService _preferencias = PreferenciasService();
  final TtsService tts = TtsService();
  late final Anunciador anunciador = Anunciador(tts);

  AjustesAccesibilidad _ajustes = AjustesAccesibilidad.porDefecto();
  List<DocumentoLeido> _historial = [];
  bool _cargando = true;

  AjustesAccesibilidad get ajustes => _ajustes;
  List<DocumentoLeido> get historial => List.unmodifiable(_historial);
  bool get cargando => _cargando;
  bool get onboardingCompletado => _ajustes.perfil != null;

  Future<void> cargar() async {
    _ajustes = await _preferencias.cargarAjustes();
    _historial = await _preferencias.cargarHistorial();
    await tts.inicializar(velocidadInicial: _ajustes.velocidadVoz);
    _cargando = false;
    notifyListeners();
  }

  /// P-01, onboarding: fija el perfil y aplica sus valores iniciales
  /// sugeridos (RF-01, RF-03).
  Future<void> elegirPerfilInicial(TipoPerfil perfil) async {
    _ajustes = AjustesAccesibilidad.paraPerfil(perfil);
    notifyListeners();
    await tts.cambiarVelocidad(_ajustes.velocidadVoz);
    await _guardar();
  }

  /// P-05, Ajustes (RF-04): cambia solo el perfil declarado, sin pisar los
  /// ajustes que el usuario ya personalizó.
  Future<void> cambiarPerfil(TipoPerfil perfil) async {
    _ajustes = _ajustes.copyWith(perfil: perfil);
    notifyListeners();
    await _guardar();
  }

  Future<void> cambiarEsquemaColor(EsquemaColor esquema) async {
    _ajustes = _ajustes.copyWith(esquemaColor: esquema);
    notifyListeners();
    await _guardar();
  }

  /// [escala] va de 1.0 (100 %) a 4.0 (400 %, tope de RNF-03).
  Future<void> cambiarEscalaTexto(double escala) async {
    _ajustes = _ajustes.copyWith(escalaTexto: escala);
    notifyListeners();
    await _guardar();
  }

  /// [velocidad] va de 0.5x a 3.0x (RF-07).
  Future<void> cambiarVelocidadVoz(double velocidad) async {
    _ajustes = _ajustes.copyWith(velocidadVoz: velocidad);
    notifyListeners();
    await tts.cambiarVelocidad(velocidad);
    await _guardar();
  }

  Future<void> alternarDescripcionIA(bool valor) async {
    _ajustes = _ajustes.copyWith(descripcionIA: valor);
    notifyListeners();
    await _guardar();
  }

  Future<void> alternarReducirAnimaciones(bool valor) async {
    _ajustes = _ajustes.copyWith(reducirAnimaciones: valor);
    notifyListeners();
    await _guardar();
  }

  Future<void> _guardar() => _preferencias.guardarAjustes(_ajustes);

  Future<void> agregarAlHistorial(DocumentoLeido documento) async {
    _historial = [documento, ..._historial].take(50).toList();
    notifyListeners();
    await _preferencias.guardarHistorial(_historial);
  }

  Future<void> borrarDelHistorial(String id) async {
    _historial = _historial.where((d) => d.id != id).toList();
    notifyListeners();
    await _preferencias.guardarHistorial(_historial);
  }

  @override
  void dispose() {
    tts.dispose();
    super.dispose();
  }
}

import 'package:flutter/material.dart';

/// Los esquemas de color entre los que el usuario puede elegir en Ajustes.
/// `altoContrasteOscuro` es el que especifica docs/04-design-system.md;
/// los otros dos existen porque no todos los ojos ven el color igual.
enum EsquemaColor { altoContrasteOscuro, altoContrasteClaro, daltonicoAzulNaranja }

extension DescripcionEsquemaColor on EsquemaColor {
  String get nombre {
    switch (this) {
      case EsquemaColor.altoContrasteOscuro:
        return 'Alto contraste oscuro';
      case EsquemaColor.altoContrasteClaro:
        return 'Alto contraste claro';
      case EsquemaColor.daltonicoAzulNaranja:
        return 'Colores adaptados (daltonismo)';
    }
  }

  String get descripcion {
    switch (this) {
      case EsquemaColor.altoContrasteOscuro:
        return 'Fondo negro, texto blanco, acciones en amarillo · contraste 15.8:1';
      case EsquemaColor.altoContrasteClaro:
        return 'Fondo blanco, texto oscuro · contraste 17.7:1';
      case EsquemaColor.daltonicoAzulNaranja:
        return 'Azul y naranja en vez de rojo/verde · seguro para protanopía y deuteranopía';
    }
  }

  String get emoji {
    switch (this) {
      case EsquemaColor.altoContrasteOscuro:
        return '🌑';
      case EsquemaColor.altoContrasteClaro:
        return '☀️';
      case EsquemaColor.daltonicoAzulNaranja:
        return '🎨';
    }
  }
}

/// Una paleta completa de colores de VÍA. `TemaVia` convierte una instancia
/// de esta clase en el `ThemeData` real que usa la app.
///
/// Los nombres de los campos describen el ROL del color (acción principal,
/// información, éxito, error), no su tono literal: en el esquema por
/// defecto `accion` es amarillo, pero en el esquema para daltonismo es
/// naranja. Así el resto del código nunca pregunta "¿es amarillo?", sino
/// "¿es el color de acción principal?" — y cambiar de esquema no rompe nada.
class ColoresVia {
  final Color fondoPrincipal; // el negro/blanco puro, para superficies extremas (splash, etc.)
  final Color fondoApp; // fondo de todas las pantallas
  final Color superficie; // tarjetas
  final Color superficie2; // tarjetas anidadas, chips
  final Color borde; // bordes de tarjeta
  final Color texto; // texto principal
  final Color textoSuave; // texto secundario
  final Color accion; // acción principal de cada pantalla, y el foco
  final Color info; // información generada por IA
  final Color exito; // confirmaciones y estados correctos
  final Color error; // errores

  const ColoresVia({
    required this.fondoPrincipal,
    required this.fondoApp,
    required this.superficie,
    required this.superficie2,
    required this.borde,
    required this.texto,
    required this.textoSuave,
    required this.accion,
    required this.info,
    required this.exito,
    required this.error,
  });

  /// Contraste verificado (WCAG, relativo a `fondoApp`): texto 21:1 ·
  /// accion 15.8:1 · info 11.4:1 · textoSuave 10.9:1.
  static const oscuro = ColoresVia(
    fondoPrincipal: Color(0xFF000000),
    fondoApp: Color(0xFF0B0F14),
    superficie: Color(0xFF151A21),
    superficie2: Color(0xFF1F2630),
    borde: Color(0xFF39424F),
    texto: Color(0xFFFFFFFF),
    textoSuave: Color(0xFFB9C2CE),
    accion: Color(0xFFFFD400),
    info: Color(0xFF4DD0FF),
    exito: Color(0xFF5BE39A),
    error: Color(0xFFFF8080),
  );

  /// Para quien prefiere fondo claro. Mismo criterio de 7:1 mínimo, verificado
  /// con la fórmula de contraste relativo de WCAG antes de fijar cada tono.
  static const claro = ColoresVia(
    fondoPrincipal: Color(0xFFFFFFFF),
    fondoApp: Color(0xFFF4F6F8),
    superficie: Color(0xFFFFFFFF),
    superficie2: Color(0xFFE7EBEF),
    borde: Color(0xFF6B7684),
    texto: Color(0xFF0B0F14),
    textoSuave: Color(0xFF3B4552),
    accion: Color(0xFF6B4A00), // 7.4:1
    info: Color(0xFF004D73), // 8.4:1
    exito: Color(0xFF0B5A2C), // 7.7:1
    error: Color(0xFF8F1F19), // 8.2:1
  );

  /// Evita depender de la distinción rojo/verde (la que falla en protanopía y
  /// deuteranopía, los dos tipos más comunes de daltonismo): usa naranja para
  /// la acción principal, azul para información, y turquesa para éxito.
  /// El rojo de error se mantiene porque ya no compite visualmente con
  /// ningún verde en esta paleta, así que sigue siendo distinguible.
  static const daltonico = ColoresVia(
    fondoPrincipal: Color(0xFF000000),
    fondoApp: Color(0xFF0A0F17),
    superficie: Color(0xFF141C28),
    superficie2: Color(0xFF1D2836),
    borde: Color(0xFF3E4C5E),
    texto: Color(0xFFFFFFFF),
    textoSuave: Color(0xFFBFCAD6),
    accion: Color(0xFFFFA733), // naranja · 9.9:1
    info: Color(0xFF63B3FF), // azul · 8.6:1
    exito: Color(0xFF4DD9C0), // turquesa · 11.0:1
    error: Color(0xFFFF8080), // 7.9:1
  );

  static ColoresVia deEsquema(EsquemaColor esquema) {
    switch (esquema) {
      case EsquemaColor.altoContrasteOscuro:
        return oscuro;
      case EsquemaColor.altoContrasteClaro:
        return claro;
      case EsquemaColor.daltonicoAzulNaranja:
        return daltonico;
    }
  }

  Brightness get brillo =>
      fondoApp.computeLuminance() < 0.5 ? Brightness.dark : Brightness.light;
}

import 'package:flutter/material.dart';
import 'colores.dart';

/// Lleva la paleta [ColoresVia] completa dentro del `ThemeData` de Flutter,
/// como una extensión de tema. Los roles que Material ya modela bien
/// (acción, información, error) están también en `colorScheme`; esta
/// extensión existe para los que no tienen un hueco estándar: `superficie2`,
/// `borde`, `textoSuave`, `exito`.
class ColoresViaExtension extends ThemeExtension<ColoresViaExtension> {
  final ColoresVia colores;
  const ColoresViaExtension(this.colores);

  @override
  ColoresViaExtension copyWith({ColoresVia? colores}) =>
      ColoresViaExtension(colores ?? this.colores);

  @override
  ColoresViaExtension lerp(ThemeExtension<ColoresViaExtension>? other, double t) {
    // Los esquemas de color no se interpolan entre sí (son elecciones
    // discretas del usuario, no una animación de color), así que al t<0.5
    // se queda con el actual y al final ya adoptó el nuevo.
    if (other is! ColoresViaExtension) return this;
    return t < 0.5 ? this : other;
  }
}

/// Acceso corto a la paleta activa: `context.coloresVia.superficie2`.
extension ColoresViaContext on BuildContext {
  ColoresVia get coloresVia =>
      Theme.of(this).extension<ColoresViaExtension>()!.colores;
}

/// Construye el `ThemeData` completo de Flutter a partir de una [ColoresVia].
/// Todo widget de la app debe tomar sus colores de `Theme.of(context)`, nunca
/// de `ColoresVia` directamente — así un solo cambio de esquema en Ajustes
/// repinta la app entera sin tocar cada pantalla.
class TemaVia {
  TemaVia._();

  static const double radioTarjeta = 18;
  static const double radioBoton = 16;
  static const double margenLateral = 20;
  static const double areaTactilMinima = 48;

  static ThemeData construir(ColoresVia c) {
    final brillo = c.brillo;

    final colorScheme = ColorScheme(
      brightness: brillo,
      primary: c.accion,
      onPrimary: c.fondoPrincipal,
      secondary: c.info,
      onSecondary: c.fondoPrincipal,
      error: c.error,
      onError: c.fondoPrincipal,
      surface: c.fondoApp,
      onSurface: c.texto,
    );

    return ThemeData(
      useMaterial3: true,
      brightness: brillo,
      colorScheme: colorScheme,
      scaffoldBackgroundColor: c.fondoApp,
      canvasColor: c.fondoApp,
      splashFactory: InkRipple.splashFactory,
      textTheme: _textTheme(c),
      appBarTheme: AppBarTheme(
        backgroundColor: c.fondoApp,
        foregroundColor: c.texto,
        elevation: 0,
        centerTitle: false,
        titleTextStyle: TextStyle(
          fontSize: 22,
          fontWeight: FontWeight.bold,
          color: c.texto,
        ),
      ),
      cardTheme: CardThemeData(
        color: c.superficie,
        elevation: 0,
        margin: const EdgeInsets.symmetric(vertical: 6),
        shape: RoundedRectangleBorder(
          borderRadius: BorderRadius.circular(radioTarjeta),
          side: BorderSide(color: c.borde, width: 2),
        ),
      ),
      elevatedButtonTheme: ElevatedButtonThemeData(
        style: ElevatedButton.styleFrom(
          backgroundColor: c.accion,
          foregroundColor: c.fondoPrincipal,
          disabledBackgroundColor: c.superficie2,
          disabledForegroundColor: c.textoSuave,
          minimumSize: const Size(double.infinity, areaTactilMinima),
          padding: const EdgeInsets.symmetric(horizontal: 24, vertical: 14),
          shape: RoundedRectangleBorder(
            borderRadius: BorderRadius.circular(radioBoton),
          ),
          textStyle: const TextStyle(fontSize: 17, fontWeight: FontWeight.bold),
        ),
      ),
      outlinedButtonTheme: OutlinedButtonThemeData(
        style: OutlinedButton.styleFrom(
          foregroundColor: c.texto,
          side: BorderSide(color: c.borde, width: 2),
          minimumSize: const Size(double.infinity, areaTactilMinima),
          padding: const EdgeInsets.symmetric(horizontal: 24, vertical: 14),
          shape: RoundedRectangleBorder(
            borderRadius: BorderRadius.circular(radioBoton),
          ),
          textStyle: const TextStyle(fontSize: 17, fontWeight: FontWeight.bold),
        ),
      ),
      iconTheme: IconThemeData(color: c.texto, size: 26),
      dividerTheme: DividerThemeData(color: c.borde, thickness: 1),
      switchTheme: SwitchThemeData(
        thumbColor: WidgetStateProperty.resolveWith(
          (states) => states.contains(WidgetState.selected)
              ? c.accion
              : c.textoSuave,
        ),
        trackColor: WidgetStateProperty.resolveWith(
          (states) => states.contains(WidgetState.selected)
              ? c.accion.withAlpha(110)
              : c.superficie2,
        ),
      ),
      sliderTheme: SliderThemeData(
        activeTrackColor: c.accion,
        inactiveTrackColor: c.superficie2,
        thumbColor: c.accion,
        overlayColor: c.accion.withAlpha(60),
        valueIndicatorColor: c.accion,
        valueIndicatorTextStyle: TextStyle(color: c.fondoPrincipal),
      ),
      progressIndicatorTheme: ProgressIndicatorThemeData(
        color: c.accion,
        linearTrackColor: c.superficie2,
      ),
      snackBarTheme: SnackBarThemeData(
        backgroundColor: c.superficie2,
        contentTextStyle: TextStyle(color: c.texto, fontSize: 16),
        behavior: SnackBarBehavior.floating,
      ),
      focusColor: c.accion.withAlpha(64),
      highlightColor: c.accion.withAlpha(40),
      splashColor: c.accion.withAlpha(30),
      extensions: [ColoresViaExtension(c)],
    );
  }

  static TextTheme _textTheme(ColoresVia c) {
    return TextTheme(
      // Título de pantalla · 26 sp · bold
      headlineLarge: TextStyle(fontSize: 26, fontWeight: FontWeight.bold, color: c.texto, height: 1.2),
      // Encabezado de sección · 19 sp · bold
      titleLarge: TextStyle(fontSize: 19, fontWeight: FontWeight.bold, color: c.texto),
      // Cuerpo · 16 sp
      bodyMedium: TextStyle(fontSize: 16, color: c.texto, height: 1.4),
      // Cuerpo de contenido leído · 18 sp
      bodyLarge: TextStyle(fontSize: 18, color: c.texto, height: 1.5),
      // Etiqueta secundaria · 14 sp
      labelLarge: TextStyle(fontSize: 14, color: c.textoSuave),
      // Micro-etiqueta · 12.5 sp · bold
      labelSmall: TextStyle(
        fontSize: 12.5,
        fontWeight: FontWeight.bold,
        color: c.textoSuave,
        letterSpacing: 1.2,
      ),
    );
  }
}

/// Una sección de contenido, delimitada por un encabezado. El lector
/// adaptativo (P-03) salta de sección en sección, no de párrafo en párrafo
/// (RF-08, RF-09) — por eso todo lo que se lee en VÍA, venga de una web, de
/// una foto con OCR o de un documento de ejemplo, se representa así.
class SeccionLectura {
  final String encabezado;
  final List<String> parrafos;
  final List<String> imagenesSinAlt;

  const SeccionLectura({
    required this.encabezado,
    this.parrafos = const [],
    this.imagenesSinAlt = const [],
  });

  String get textoCompleto =>
      parrafos.isEmpty ? encabezado : '$encabezado. ${parrafos.join(' ')}';
}

/// De dónde salió el contenido que se está leyendo. Cambia el subtítulo de
/// P-03 y el ícono en el historial.
enum OrigenLectura { web, fotoOcr, ejemplo }

class ContenidoLectura {
  final String titulo;
  final String fuente;
  final OrigenLectura origen;
  final List<SeccionLectura> secciones;

  const ContenidoLectura({
    required this.titulo,
    required this.fuente,
    required this.origen,
    required this.secciones,
  });

  int get totalImagenesSinAlt =>
      secciones.fold(0, (total, s) => total + s.imagenesSinAlt.length);

  String get textoCompleto => secciones.map((s) => s.textoCompleto).join('\n\n');
}

/// De dónde vino el contenido de un [DocumentoLeido]. Sirve para mostrar un
/// ícono distinto en el historial y para saber cómo volver a reproducirlo.
enum OrigenDocumento { fotoOcr, web, texto }

/// Un documento que VÍA ya leyó en voz alta, guardado para poder volver a
/// escucharlo (RF-14, Fase 9).
class DocumentoLeido {
  final String id;
  final String titulo;
  final String contenido;
  final OrigenDocumento origen;
  final DateTime fecha;

  const DocumentoLeido({
    required this.id,
    required this.titulo,
    required this.contenido,
    required this.origen,
    required this.fecha,
  });

  Map<String, dynamic> aJson() => {
        'id': id,
        'titulo': titulo,
        'contenido': contenido,
        'origen': origen.name,
        'fecha': fecha.toIso8601String(),
      };

  factory DocumentoLeido.desdeJson(Map<String, dynamic> json) {
    return DocumentoLeido(
      id: json['id'] as String,
      titulo: json['titulo'] as String,
      contenido: json['contenido'] as String,
      origen: OrigenDocumento.values.firstWhere(
        (o) => o.name == json['origen'],
        orElse: () => OrigenDocumento.texto,
      ),
      fecha: DateTime.parse(json['fecha'] as String),
    );
  }
}

import '../../core/theme/colores.dart';

/// Las tres formas de recibir la información que VÍA ofrece en el onboarding
/// (P-01). No cambia qué funciones existen, solo los valores iniciales de
/// [AjustesAccesibilidad] y el saludo de la pantalla de inicio.
enum TipoPerfil { cegueraTotal, bajaVision, daltonismo }

extension InfoTipoPerfil on TipoPerfil {
  String get titulo {
    switch (this) {
      case TipoPerfil.cegueraTotal:
        return 'Solo voz';
      case TipoPerfil.bajaVision:
        return 'Texto ampliado + voz';
      case TipoPerfil.daltonismo:
        return 'Colores adaptados';
    }
  }

  String get descripcion {
    switch (this) {
      case TipoPerfil.cegueraTotal:
        return 'Ceguera total · lectura por audio y gestos';
      case TipoPerfil.bajaVision:
        return 'Baja visión · fuente 200 % y alto contraste';
      case TipoPerfil.daltonismo:
        return 'Daltonismo · paletas seguras y etiquetas';
    }
  }

  String get emoji {
    switch (this) {
      case TipoPerfil.cegueraTotal:
        return '🔊';
      case TipoPerfil.bajaVision:
        return '🔍';
      case TipoPerfil.daltonismo:
        return '🎨';
    }
  }
}

/// Todo lo que el usuario personaliza en VÍA. Se guarda completo en
/// `shared_preferences` (ver `preferencias_service.dart`) y se aplica a la
/// app entera a través de `PerfilProvider`.
class AjustesAccesibilidad {
  final TipoPerfil? perfil; // null = onboarding todavía no completado
  final EsquemaColor esquemaColor;
  final double escalaTexto; // 1.0 = 100 % ... hasta 4.0 = 400 % (RNF-03)
  final double velocidadVoz; // 0.5x a 3.0x (RF-07)
  final bool descripcionIA; // Fase 11
  final bool reducirAnimaciones;

  const AjustesAccesibilidad({
    required this.perfil,
    required this.esquemaColor,
    required this.escalaTexto,
    required this.velocidadVoz,
    required this.descripcionIA,
    required this.reducirAnimaciones,
  });

  factory AjustesAccesibilidad.porDefecto() => const AjustesAccesibilidad(
        perfil: null,
        esquemaColor: EsquemaColor.altoContrasteOscuro,
        escalaTexto: 1.0,
        velocidadVoz: 1.0,
        descripcionIA: true,
        reducirAnimaciones: false,
      );

  /// Valores iniciales sugeridos al elegir un perfil en el onboarding.
  /// El usuario puede cambiarlos todos después, en Ajustes (RF-04).
  factory AjustesAccesibilidad.paraPerfil(TipoPerfil perfil) {
    switch (perfil) {
      case TipoPerfil.cegueraTotal:
        return AjustesAccesibilidad.porDefecto().copyWith(perfil: perfil);
      case TipoPerfil.bajaVision:
        return AjustesAccesibilidad.porDefecto().copyWith(
          perfil: perfil,
          escalaTexto: 2.0,
        );
      case TipoPerfil.daltonismo:
        return AjustesAccesibilidad.porDefecto().copyWith(
          perfil: perfil,
          esquemaColor: EsquemaColor.daltonicoAzulNaranja,
        );
    }
  }

  AjustesAccesibilidad copyWith({
    TipoPerfil? perfil,
    EsquemaColor? esquemaColor,
    double? escalaTexto,
    double? velocidadVoz,
    bool? descripcionIA,
    bool? reducirAnimaciones,
  }) {
    return AjustesAccesibilidad(
      perfil: perfil ?? this.perfil,
      esquemaColor: esquemaColor ?? this.esquemaColor,
      escalaTexto: escalaTexto ?? this.escalaTexto,
      velocidadVoz: velocidadVoz ?? this.velocidadVoz,
      descripcionIA: descripcionIA ?? this.descripcionIA,
      reducirAnimaciones: reducirAnimaciones ?? this.reducirAnimaciones,
    );
  }

  Map<String, dynamic> aJson() => {
        'perfil': perfil?.name,
        'esquemaColor': esquemaColor.name,
        'escalaTexto': escalaTexto,
        'velocidadVoz': velocidadVoz,
        'descripcionIA': descripcionIA,
        'reducirAnimaciones': reducirAnimaciones,
      };

  factory AjustesAccesibilidad.desdeJson(Map<String, dynamic> json) {
    final base = AjustesAccesibilidad.porDefecto();
    return base.copyWith(
      perfil: _porNombre(TipoPerfil.values, json['perfil'] as String?),
      esquemaColor:
          _porNombre(EsquemaColor.values, json['esquemaColor'] as String?),
      escalaTexto: (json['escalaTexto'] as num?)?.toDouble(),
      velocidadVoz: (json['velocidadVoz'] as num?)?.toDouble(),
      descripcionIA: json['descripcionIA'] as bool?,
      reducirAnimaciones: json['reducirAnimaciones'] as bool?,
    );
  }

  static T? _porNombre<T extends Enum>(List<T> valores, String? nombre) {
    if (nombre == null) return null;
    for (final valor in valores) {
      if (valor.name == nombre) return valor;
    }
    return null;
  }
}

import 'package:html/dom.dart';
import 'package:html/parser.dart' as html_parser;
import 'package:http/http.dart' as http;
import '../models/contenido_lectura.dart';

/// Abre una URL, extrae su contenido y lo reconstruye con jerarquía de
/// encabezados (RF-18) y marca las imágenes sin texto alternativo (RF-19).
/// La descripción de esas imágenes con IA es la Fase 11 — aquí solo se
/// detectan y se dejan pendientes, nunca se inventa una descripción.
class LectorWebService {
  Future<ContenidoLectura> leerUrl(String url) async {
    final uri = Uri.parse(url.contains('://') ? url : 'https://$url');
    final respuesta = await http.get(uri, headers: {
      'User-Agent': 'Mozilla/5.0 (compatible; VIA-lector-accesible/1.0)',
    }).timeout(const Duration(seconds: 15));

    if (respuesta.statusCode != 200) {
      throw Exception(
        'No se pudo abrir la página (código ${respuesta.statusCode}).',
      );
    }

    final documento = html_parser.parse(respuesta.body);
    final tituloTag = documento.querySelector('title')?.text.trim();
    final titulo = (tituloTag != null && tituloTag.isNotEmpty) ? tituloTag : uri.host;

    final encabezados = documento.querySelectorAll('h1, h2, h3');
    final secciones = encabezados.isEmpty
        ? [_seccionUnica(documento, titulo)]
        : _seccionesPorEncabezado(encabezados);

    return ContenidoLectura(
      titulo: titulo,
      fuente: '${uri.host} · reconstruido',
      origen: OrigenLectura.web,
      secciones: secciones,
    );
  }

  bool _esEncabezado(Element e) =>
      e.localName == 'h1' || e.localName == 'h2' || e.localName == 'h3';

  SeccionLectura _seccionUnica(Document documento, String titulo) {
    final parrafos = (documento.body?.querySelectorAll('p') ?? [])
        .map((p) => p.text.trim())
        .where((t) => t.isNotEmpty)
        .take(30)
        .toList();
    return SeccionLectura(
      encabezado: titulo,
      parrafos: parrafos,
      imagenesSinAlt: _imagenesSinAlt(documento),
    );
  }

  List<SeccionLectura> _seccionesPorEncabezado(List<Element> encabezados) {
    final secciones = <SeccionLectura>[];
    for (final actual in encabezados) {
      final parrafos = <String>[];
      final imagenes = <String>[];
      Element? nodo = actual.nextElementSibling;
      while (nodo != null && !_esEncabezado(nodo)) {
        if (nodo.localName == 'p') {
          final t = nodo.text.trim();
          if (t.isNotEmpty) parrafos.add(t);
        }
        for (final img in nodo.querySelectorAll('img')) {
          final alt = img.attributes['alt'];
          if (alt == null || alt.trim().isEmpty) {
            final src = img.attributes['src'];
            if (src != null && src.isNotEmpty) imagenes.add(src);
          }
        }
        nodo = nodo.nextElementSibling;
      }
      final titulo = actual.text.trim();
      if (titulo.isEmpty) continue;
      secciones.add(SeccionLectura(
        encabezado: titulo,
        parrafos: parrafos,
        imagenesSinAlt: imagenes,
      ));
    }
    return secciones;
  }

  List<String> _imagenesSinAlt(Document documento) {
    return documento
        .querySelectorAll('img')
        .where((img) {
          final alt = img.attributes['alt'];
          return alt == null || alt.trim().isEmpty;
        })
        .map((img) => img.attributes['src'] ?? '')
        .where((s) => s.isNotEmpty)
        .toList();
  }
}

import 'package:google_mlkit_text_recognition/google_mlkit_text_recognition.dart';

/// Envuelve `google_mlkit_text_recognition`. Corre en el propio dispositivo,
/// sin nube (RNF-08) — coherente con la regla de arquitectura #3.
class OcrService {
  final TextRecognizer _reconocedor =
      TextRecognizer(script: TextRecognitionScript.latin);

  /// Extrae el texto de la foto en [rutaImagen]. Devuelve cadena vacía si no
  /// encontró texto reconocible.
  Future<String> reconocerTexto(String rutaImagen) async {
    final imagen = InputImage.fromFilePath(rutaImagen);
    final resultado = await _reconocedor.processImage(imagen);
    return resultado.text.trim();
  }

  void dispose() {
    _reconocedor.close();
  }
}

import 'dart:convert';
import 'package:shared_preferences/shared_preferences.dart';
import '../models/perfil_accesibilidad.dart';
import '../models/documento_leido.dart';

/// Único lugar del proyecto que toca `shared_preferences` directamente
/// (regla de arquitectura #2: los paquetes externos se quedan envueltos
/// en `data/services/`).
class PreferenciasService {
  static const _claveAjustes = 'via_ajustes_accesibilidad';
  static const _claveHistorial = 'via_historial_documentos';

  Future<AjustesAccesibilidad> cargarAjustes() async {
    final prefs = await SharedPreferences.getInstance();
    final texto = prefs.getString(_claveAjustes);
    if (texto == null) return AjustesAccesibilidad.porDefecto();
    try {
      return AjustesAccesibilidad.desdeJson(
        jsonDecode(texto) as Map<String, dynamic>,
      );
    } catch (_) {
      // Si el JSON guardado quedó corrupto por una versión vieja de la app,
      // no tumbamos el arranque: volvemos a los valores por defecto.
      return AjustesAccesibilidad.porDefecto();
    }
  }

  Future<void> guardarAjustes(AjustesAccesibilidad ajustes) async {
    final prefs = await SharedPreferences.getInstance();
    await prefs.setString(_claveAjustes, jsonEncode(ajustes.aJson()));
  }

  Future<List<DocumentoLeido>> cargarHistorial() async {
    final prefs = await SharedPreferences.getInstance();
    final lista = prefs.getStringList(_claveHistorial);
    if (lista == null) return [];
    return lista
        .map((texto) {
          try {
            return DocumentoLeido.desdeJson(
              jsonDecode(texto) as Map<String, dynamic>,
            );
          } catch (_) {
            return null;
          }
        })
        .whereType<DocumentoLeido>()
        .toList();
  }

  Future<void> guardarHistorial(List<DocumentoLeido> documentos) async {
    final prefs = await SharedPreferences.getInstance();
    await prefs.setStringList(
      _claveHistorial,
      documentos.map((d) => jsonEncode(d.aJson())).toList(),
    );
  }
}

import 'package:speech_to_text/speech_to_text.dart';

/// Envuelve `speech_to_text`. Igual que `TtsService`, es el único archivo
/// que importa el paquete externo (regla de arquitectura #2).
class SttService {
  final SpeechToText _stt = SpeechToText();
  bool _disponible = false;

  bool get disponible => _disponible;
  bool get escuchando => _stt.isListening;

  Future<bool> inicializar({
    void Function(String error)? onError,
    void Function(String estado)? onEstado,
  }) async {
    _disponible = await _stt.initialize(
      onError: (e) => onError?.call(e.errorMsg),
      onStatus: (estado) => onEstado?.call(estado),
    );
    return _disponible;
  }

  /// Empieza a escuchar. [onResultado] se llama cada vez que hay una
  /// transcripción nueva (parcial o final) — quien llama decide qué hacer
  /// con `esFinal`.
  Future<void> escuchar({
    required void Function(String texto, bool esFinal) onResultado,
  }) async {
    if (!_disponible) return;
    await _stt.listen(
      listenOptions: SpeechListenOptions(localeId: 'es_PE'),
      onResult: (r) => onResultado(r.recognizedWords, r.finalResult),
    );
  }

  Future<void> detener() => _stt.stop();

  Future<void> cancelar() => _stt.cancel();
}

import 'package:flutter_tts/flutter_tts.dart';

/// Envuelve `flutter_tts`. Es el único archivo del proyecto que lo importa
/// (regla de arquitectura #2 de docs/03-arquitectura.md): si mañana cambiamos
/// de paquete de voz, solo se toca este archivo.
class TtsService {
  final FlutterTts _tts = FlutterTts();
  bool _listo = false;

  Future<void> inicializar({double velocidadInicial = 1.0}) async {
    if (_listo) return;
    try {
      final idiomas = await _tts.getLanguages;
      final disponibles =
          idiomas is List ? idiomas.map((e) => e.toString()).toList() : <String>[];
      final idioma = disponibles.contains('es-PE')
          ? 'es-PE'
          : (disponibles.contains('es-ES') ? 'es-ES' : 'es-PE');
      await _tts.setLanguage(idioma);
    } catch (_) {
      // Si el dispositivo no reporta idiomas (pasa en algunos emuladores),
      // seguimos con es-PE como valor por defecto; el motor decide el resto.
      await _tts.setLanguage('es-PE');
    }
    await _tts.setPitch(1.0);
    await _tts.awaitSpeakCompletion(true);
    await cambiarVelocidad(velocidadInicial);
    _listo = true;
  }

  /// Dice [texto] en voz alta. Si [interrumpir] es true, corta lo que se
  /// esté diciendo antes de empezar — se usa para avisos urgentes como los
  /// de la guía de captura de Ojo IA.
  Future<void> hablar(String texto, {bool interrumpir = false}) async {
    if (texto.trim().isEmpty) return;
    if (!_listo) await inicializar();
    if (interrumpir) await detener();
    await _tts.speak(texto);
  }

  Future<void> detener() => _tts.stop();

  Future<void> pausar() => _tts.pause();

  /// [x] es el multiplicador de velocidad de VÍA, donde 1.0 es normal
  /// (rango 0.5x a 3x, ver docs/04-design-system.md). `flutter_tts` espera
  /// un valor de 0.0 a 1.0, así que se reescala aquí: este es el único lugar
  /// del proyecto que necesita conocer ese detalle de la librería.
  Future<void> cambiarVelocidad(double x) async {
    final valorPlugin = (x / 2.6).clamp(0.05, 1.0);
    await _tts.setSpeechRate(valorPlugin);
  }

  void dispose() {
    _tts.stop();
  }
}

import 'package:flutter/material.dart';
import 'package:provider/provider.dart';
import '../../core/state/perfil_provider.dart';
import '../../core/theme/colores.dart';
import '../../core/theme/tema_via.dart';
import '../../data/models/perfil_accesibilidad.dart';
import '../../shared/widgets/tarjeta_accesible.dart';
import '../historial/historial_screen.dart';

/// P-05 · Ajustes de accesibilidad. Todo lo personalizable de VÍA vive
/// aquí: perfil, esquema de color (incluyendo las paletas seguras para
/// daltonismo), tamaño de texto, velocidad de voz y visualización. Cada
/// cambio se aplica al instante y se anuncia (docs/05-pantallas.md).
class AjustesScreen extends StatefulWidget {
  const AjustesScreen({super.key});

  @override
  State<AjustesScreen> createState() => _AjustesScreenState();
}

class _AjustesScreenState extends State<AjustesScreen> {
  bool _anunciado = false;

  @override
  void didChangeDependencies() {
    super.didChangeDependencies();
    if (!_anunciado) {
      _anunciado = true;
      WidgetsBinding.instance.addPostFrameCallback((_) {
        if (!mounted) return;
        context.read<PerfilProvider>().anunciador.anunciar(
              'Ajustes de accesibilidad. Perfil, color, lectura y visualización.',
            );
      });
    }
  }

  @override
  Widget build(BuildContext context) {
    final c = context.coloresVia;
    final provider = context.watch<PerfilProvider>();
    final ajustes = provider.ajustes;

    return Scaffold(
      appBar: AppBar(title: const Text('Ajustes de accesibilidad')),
      body: SafeArea(
        child: ListView(
          padding: const EdgeInsets.all(TemaVia.margenLateral),
          children: [
            Text('Se aplican a todo el contenido', style: TextStyle(color: c.textoSuave)),
            const SizedBox(height: 18),

            _tituloSeccion(context, 'Perfil'),
            ...TipoPerfil.values.map((perfil) => Padding(
                  padding: const EdgeInsets.only(bottom: 10),
                  child: TarjetaAccesible(
                    emoji: perfil.emoji,
                    titulo: perfil.titulo,
                    descripcion: perfil.descripcion,
                    seleccionada: ajustes.perfil == perfil,
                    acento: ajustes.perfil == perfil ? AcentoTarjeta.accion : AcentoTarjeta.neutro,
                    onTap: () {
                      provider.cambiarPerfil(perfil);
                      provider.anunciador.anunciar('Perfil: ${perfil.titulo}.');
                    },
                  ),
                )),

            _tituloSeccion(context, 'Color e interfaz'),
            ...EsquemaColor.values.map((esquema) => Padding(
                  padding: const EdgeInsets.only(bottom: 10),
                  child: TarjetaAccesible(
                    emoji: esquema.emoji,
                    titulo: esquema.nombre,
                    descripcion: esquema.descripcion,
                    seleccionada: ajustes.esquemaColor == esquema,
                    acento: ajustes.esquemaColor == esquema ? AcentoTarjeta.info : AcentoTarjeta.neutro,
                    onTap: () {
                      provider.cambiarEsquemaColor(esquema);
                      provider.anunciador.anunciar('Esquema de color: ${esquema.nombre}.');
                    },
                  ),
                )),

            _tituloSeccion(context, 'Lectura'),
            _tarjetaDeslizador(
              context,
              titulo: 'Tamaño de texto',
              valorMostrado: '${(ajustes.escalaTexto * 100).round()} %',
              nota: 'Escalable hasta 400 % sin pérdida de contenido (WCAG 1.4.4)',
              valor: ajustes.escalaTexto,
              min: 1.0,
              max: 4.0,
              divisiones: 30,
              onChanged: (v) => provider.cambiarEscalaTexto(v),
              onChangeEnd: (v) => provider.anunciador.anunciar(
                'Tamaño de texto, ${(v * 100).round()} por ciento.',
              ),
            ),
            _tarjetaDeslizador(
              context,
              titulo: 'Velocidad de voz',
              valorMostrado: '${ajustes.velocidadVoz.toStringAsFixed(2)}×',
              valor: ajustes.velocidadVoz,
              min: 0.5,
              max: 3.0,
              divisiones: 25,
              onChanged: (v) => provider.cambiarVelocidadVoz(v),
              onChangeEnd: (v) => provider.anunciador.anunciar(
                'Velocidad de voz, ${v.toStringAsFixed(2)} veces.',
              ),
            ),

            _tituloSeccion(context, 'Visualización'),
            _tarjetaInterruptor(
              context,
              titulo: 'Descripción de imágenes con IA',
              descripcion: 'Genera alt cuando la web no lo trae (Fase 11)',
              valor: ajustes.descripcionIA,
              onChanged: (v) {
                provider.alternarDescripcionIA(v);
                provider.anunciador.anunciar('Descripción con IA ${v ? "activada" : "desactivada"}.');
              },
            ),
            _tarjetaInterruptor(
              context,
              titulo: 'Reducir animaciones',
              descripcion: 'Evita mareo y distracción',
              valor: ajustes.reducirAnimaciones,
              onChanged: (v) {
                provider.alternarReducirAnimaciones(v);
                provider.anunciador.anunciar(
                  'Reducir animaciones ${v ? "activado" : "desactivado"}.',
                );
              },
            ),

            _tituloSeccion(context, 'Historial'),
            Card(
              child: ListTile(
                leading: Icon(Icons.history_rounded, color: c.texto),
                title: Text('Documentos leídos', style: TextStyle(color: c.texto)),
                subtitle: Text(
                  '${provider.historial.length} guardado(s)',
                  style: TextStyle(color: c.textoSuave),
                ),
                trailing: Icon(Icons.chevron_right_rounded, color: c.textoSuave),
                onTap: () => Navigator.of(context).push(
                  MaterialPageRoute(builder: (_) => const HistorialScreen()),
                ),
              ),
            ),
            const SizedBox(height: 24),
          ],
        ),
      ),
    );
  }

  Widget _tituloSeccion(BuildContext context, String texto) {
    final c = context.coloresVia;
    return Padding(
      padding: const EdgeInsets.only(top: 6, bottom: 10),
      child: Text(
        texto.toUpperCase(),
        style: TextStyle(
          fontSize: 13,
          fontWeight: FontWeight.bold,
          letterSpacing: 1.2,
          color: c.textoSuave,
        ),
      ),
    );
  }

  Widget _tarjetaDeslizador(
    BuildContext context, {
    required String titulo,
    required String valorMostrado,
    required double valor,
    required double min,
    required double max,
    required int divisiones,
    required ValueChanged<double> onChanged,
    required ValueChanged<double> onChangeEnd,
    String? nota,
  }) {
    final c = context.coloresVia;
    return Card(
      child: Padding(
        padding: const EdgeInsets.fromLTRB(16, 12, 16, 4),
        child: Column(
          crossAxisAlignment: CrossAxisAlignment.start,
          children: [
            Row(
              mainAxisAlignment: MainAxisAlignment.spaceBetween,
              children: [
                Text(titulo, style: TextStyle(fontSize: 17, color: c.texto)),
                Container(
                  padding: const EdgeInsets.symmetric(horizontal: 10, vertical: 4),
                  decoration: BoxDecoration(
                    color: c.accion.withAlpha(40),
                    borderRadius: BorderRadius.circular(999),
                  ),
                  child: Text(
                    valorMostrado,
                    style: TextStyle(color: c.accion, fontWeight: FontWeight.bold, fontSize: 13),
                  ),
                ),
              ],
            ),
            Semantics(
              slider: true,
              label: '$titulo, $valorMostrado',
              child: Slider(
                value: valor,
                min: min,
                max: max,
                divisions: divisiones,
                onChanged: onChanged,
                onChangeEnd: onChangeEnd,
              ),
            ),
            if (nota != null)
              Padding(
                padding: const EdgeInsets.only(bottom: 10),
                child: Text(nota, style: TextStyle(fontSize: 13, color: c.textoSuave)),
              ),
          ],
        ),
      ),
    );
  }

  Widget _tarjetaInterruptor(
    BuildContext context, {
    required String titulo,
    required String descripcion,
    required bool valor,
    required ValueChanged<bool> onChanged,
  }) {
    final c = context.coloresVia;
    return Card(
      child: Padding(
        padding: const EdgeInsets.symmetric(horizontal: 16, vertical: 6),
        child: Row(
          children: [
            Expanded(
              child: Column(
                crossAxisAlignment: CrossAxisAlignment.start,
                children: [
                  Text(titulo, style: TextStyle(fontSize: 17, color: c.texto)),
                  const SizedBox(height: 2),
                  Text(descripcion, style: TextStyle(fontSize: 13, color: c.textoSuave)),
                ],
              ),
            ),
            Semantics(
              label: '$titulo, ${valor ? "activado" : "desactivado"}',
              toggled: valor,
              child: Switch(value: valor, onChanged: onChanged),
            ),
          ],
        ),
      ),
    );
  }
}

