      decoration: BoxDecoration(
        color: c.fondoApp,
        border: Border(top: BorderSide(color: c.borde, width: 1)),
      ),
      child: SafeArea(
        top: false,
        child: Padding(
          padding: const EdgeInsets.symmetric(vertical: 6),
          child: Row(
            children: List.generate(_pestanas.length, (i) {
              final activa = i == indiceActual;
              final pestana = _pestanas[i];
              return Expanded(
                child: Semantics(
                  button: true,
                  selected: activa,
                  label:
                      '${pestana.etiqueta}, pestaña ${i + 1} de ${_pestanas.length}',
                  excludeSemantics: true,
                  child: InkWell(
                    onTap: () {
                      if (!activa) {
                        TipoVibracion.cambioFoco.ejecutar();
                        onCambiar(i);
                      }
                    },
                    child: ConstrainedBox(
                      constraints:
                          const BoxConstraints(minHeight: TemaVia.areaTactilMinima),
                      child: Column(
                        mainAxisSize: MainAxisSize.min,
                        mainAxisAlignment: MainAxisAlignment.center,
                        children: [
                          Icon(
                            pestana.icono,
                            color: activa ? c.accion : c.textoSuave,
                            size: 24,
                          ),
                          const SizedBox(height: 3),
                          Text(
                            pestana.etiqueta,
                            style: TextStyle(
                              fontSize: 12,
                              fontWeight: activa ? FontWeight.bold : FontWeight.normal,
                              color: activa ? c.accion : c.textoSuave,
                            ),
                          ),
                        ],
                      ),
                    ),
                  ),
                ),
              );
            }),
          ),
        ),
      ),
    );
  }
}

import 'package:flutter/material.dart';
import '../../core/accessibility/anunciador.dart';
import '../../core/theme/tema_via.dart';

/// Botón con las reglas que no se negocian (docs/04-design-system.md):
/// 48×48 dp mínimo, etiqueta semántica de la ACCIÓN (no del ícono) y
/// vibración al tocar.
class BotonAccesible extends StatelessWidget {
  final String texto;
  final String etiquetaSemantica;
  final VoidCallback? onPressed;
  final IconData? icono;
  final bool destacado; // true = botón amarillo (acción principal); false = contorneado
  final TipoVibracion vibracion;

  const BotonAccesible({
    super.key,
    required this.texto,
    required this.onPressed,
    String? etiquetaSemantica,
    this.icono,
    this.destacado = true,
    this.vibracion = TipoVibracion.accionEjecutada,
  }) : etiquetaSemantica = etiquetaSemantica ?? texto;

  @override
  Widget build(BuildContext context) {
    final contenido = icono == null
        ? Text(texto, textAlign: TextAlign.center)
        : Row(
            mainAxisSize: MainAxisSize.min,
            mainAxisAlignment: MainAxisAlignment.center,
            children: [
              Icon(icono, size: 22),
              const SizedBox(width: 10),
              Flexible(child: Text(texto, textAlign: TextAlign.center)),
            ],
          );

    void alPresionar() {
      vibracion.ejecutar();
      onPressed?.call();
    }

    return Semantics(
      button: true,
      label: etiquetaSemantica,
      excludeSemantics: true,
      child: ConstrainedBox(
        constraints: const BoxConstraints(minHeight: TemaVia.areaTactilMinima),
        child: destacado
            ? ElevatedButton(onPressed: onPressed == null ? null : alPresionar, child: contenido)
            : OutlinedButton(onPressed: onPressed == null ? null : alPresionar, child: contenido),
      ),
    );
  }
}

import 'package:flutter/material.dart';
import '../../core/theme/tema_via.dart';

/// De qué manera se pinta un [ChipVia].
enum EstiloChip { normal, activo, exito }

/// La "píldora" de estado que aparece en varias pantallas: "✓ Contraste
/// 15.8:1", "Texto 180 %", "● En llamada · 00:42" (docs/05-pantallas.md).
/// Nunca lleva solo color: siempre trae texto, por RNF-07.
class ChipVia extends StatelessWidget {
  final String texto;
  final EstiloChip estilo;

  const ChipVia({super.key, required this.texto, this.estilo = EstiloChip.normal});

  @override
  Widget build(BuildContext context) {
    final c = context.coloresVia;
    late final Color fondo;
    late final Color borde;
    late final Color tinta;
    switch (estilo) {
      case EstiloChip.activo:
        fondo = c.accion.withAlpha(40);
        borde = c.accion;
        tinta = c.accion;
        break;
      case EstiloChip.exito:
        fondo = c.exito.withAlpha(35);
        borde = c.exito;
        tinta = c.exito;
        break;
      case EstiloChip.normal:
        fondo = c.superficie2;
        borde = c.borde;
        tinta = c.textoSuave;
        break;
    }
    return Container(
      padding: const EdgeInsets.symmetric(horizontal: 12, vertical: 7),
      decoration: BoxDecoration(
        color: fondo,
        borderRadius: BorderRadius.circular(999),
        border: Border.all(color: borde, width: 1.5),
      ),
      child: Text(
        texto,
        style: TextStyle(fontSize: 13, fontWeight: FontWeight.w700, color: tinta),
      ),
    );
  }
}

import 'package:flutter/material.dart';
import '../../core/accessibility/anunciador.dart';
import '../../core/theme/tema_via.dart';

/// De qué color es el círculo del ícono de la tarjeta.
enum AcentoTarjeta { accion, info, neutro }

/// La tarjeta grande de ícono + título + descripción de P-01 y P-02
/// (docs/05-pantallas.md): 48 dp mínimos, semántica de la acción completa
/// y borde amarillo + halo cuando está seleccionada.
class TarjetaAccesible extends StatelessWidget {
  final String emoji;
  final String titulo;
  final String descripcion;
  final String? etiquetaSemantica;
  final VoidCallback? onTap;
  final bool seleccionada;
  final AcentoTarjeta acento;

  const TarjetaAccesible({
    super.key,
    required this.emoji,
    required this.titulo,
    required this.descripcion,
    this.etiquetaSemantica,
    this.onTap,
    this.seleccionada = false,
    this.acento = AcentoTarjeta.neutro,
  });

  @override
  Widget build(BuildContext context) {
    final c = context.coloresVia;
    final texto = Theme.of(context).textTheme;

    final colorIcono = switch (acento) {
      AcentoTarjeta.accion => c.accion,
      AcentoTarjeta.info => c.info,
      AcentoTarjeta.neutro => c.superficie2,
    };
    final colorSobreIcono =
        acento == AcentoTarjeta.neutro ? c.texto : c.fondoPrincipal;
    final colorBorde = seleccionada ? c.accion : c.borde;

    final tarjeta = Container(
      padding: const EdgeInsets.all(16),
      decoration: BoxDecoration(
        color: c.superficie,
        borderRadius: BorderRadius.circular(TemaVia.radioTarjeta),
        border: Border.all(color: colorBorde, width: seleccionada ? 3 : 2),
        boxShadow: seleccionada
            ? [BoxShadow(color: c.accion.withAlpha(60), blurRadius: 10, spreadRadius: 2)]
            : null,
      ),
      child: Row(
        crossAxisAlignment: CrossAxisAlignment.center,
        children: [
          Container(
            width: 48,
            height: 48,
            alignment: Alignment.center,
            decoration: BoxDecoration(color: colorIcono, shape: BoxShape.circle),
            child: Text(emoji, style: TextStyle(fontSize: 22, color: colorSobreIcono)),
          ),
          const SizedBox(width: 14),
          Expanded(
            child: Column(
              crossAxisAlignment: CrossAxisAlignment.start,
              mainAxisSize: MainAxisSize.min,
              children: [
                Text(titulo, style: texto.titleLarge),
                const SizedBox(height: 3),
                Text(descripcion, style: texto.labelLarge),
              ],
            ),
          ),
          if (seleccionada) ...[
            const SizedBox(width: 8),
            Icon(Icons.check_circle, color: c.accion, size: 26),
          ],
        ],
      ),
    );

    if (onTap == null) return tarjeta;

    return Semantics(
      button: true,
      selected: seleccionada,
      label: etiquetaSemantica ?? '$titulo. $descripcion',
      excludeSemantics: true,
      child: Material(
        color: Colors.transparent,
        child: InkWell(
          borderRadius: BorderRadius.circular(TemaVia.radioTarjeta),
          onTap: () {
            TipoVibracion.accionEjecutada.ejecutar();
            onTap!();
          },
          child: ConstrainedBox(
            constraints: const BoxConstraints(minHeight: TemaVia.areaTactilMinima),
            child: tarjeta,
          ),
        ),
      ),
    );
  }
}
